/* المُلهم، «تعلّم»: مكتبة المؤلفين، كتاب «تأسيس عقلية الطفل» */
window.HH_LIB=window.HH_LIB||{};
window.HH_LIB["mind"]={"id":"mind","title":"تأسيس عقلية الطفل","sub":"","author":"أ.د. عبد الكريم بكار","coauthors":[],"translator":"","publisher":"دار وجوه للنشر والتوزيع، الرياض","year":"1433 هجرية، 2012م","edition":"الطبعة الثانية (طبعة ثانية مهذبة ومدققة)","series":"","lead":"كتاب تربوي يقدم للمربين المفاهيم والأساليب التي تبني عقل الطفل المسلم، في قسمين: الأول عن الدماغ والقراءة ووعي الطفل بذاته والمبادئ الحياتية العامة، والثاني عن الطفل المفكر وأنواع التفكير وتكوين المفاهيم. يقول المؤلف: «وسأبذل جهدي في سبيل توفير الأفكار والأساليب والأدوات التي تساعدنا على تأسيس عقلية الطفل المسلم على نحو يمكّنه من فهم زمانه ومواجهة تحدياته».","audience":"الآباء والمربون والمعلمون","bio":"","chapters":[{"k":"c1","t":"توطئة","q":"كيف ينمو عقل الطفل، وما دور القراءة في ذلك؟","essence":"العقل يعمل بالمفاهيم، والقراءة أقوى غذائه","kw":["المفاهيم","البيئة المحفزة","القراءة"],"sections":[{"t":"العقل وأدواته","pg":15,"key":"أما العقل فإن أدواته عبارة عن رموز لغوية وتعريفات ومصطلحات وأفكار ومفاهيم ونظريات ورؤى ومعادلات","p":["كذلك العقل يجد نفسه عاجزاً عن التفكير في أمور لا يملك معلومات وأفكاراً عنها."],"items":[{"h":"تشبيه الحداد","x":"كما يعجز الحداد عن العمل من غير سندان ومطرقة، يعجز العقل عن التفكير من غير معلومات وأفكار."},{"h":"مفاتيح الموضوع","x":"الأطفال حين يسمعون الكبار يسألون عن معاني الكلمات التي تشكل مفاتيح الموضوع، لأنهم من غيرها لا يستطيعون استيعابه."}]},{"t":"مرحلة التساؤل وتشكل المفاهيم","pg":16,"key":"وقد أطلق أحد الباحثين على هذه المرحلة اسم (مرحلة التساؤل) حيث تدل بعض الدراسات على أن ما بين (10% إلى 15%) من حديث الطفل في هذه المرحلة يكون عبارة عن أسئلة.","p":["إن الطفل يظن في البداية أن كل رجل أب، كما يظن أن كل امرأة أم وكل طفل أخ","إن المفاهيم تشكل معظم النشاط العقلي"],"items":[{"h":"الطفولة المبكرة","x":"تقع بين ثلاث وست سنوات، وفيها يكثر سؤال الطفل: ماذا ولماذا وكيف ومن أين."},{"h":"من المحسوس إلى المجرد","x":"تبدأ المفاهيم بالأشياء المحسوسة كالزمان والمكان والأشكال، ثم تنتهي إلى المعاني المجردة كالصدق والأمانة."},{"h":"الطفل الذكي","x":"يمتلك مفاهيم أكثر من أقرانه، وتكون مفاهيمه أكثر تحديداً وأفضل دلالة."}]},{"t":"البيئة المحفزة ونمو الدماغ","pg":18,"key":"عقول الأطفال تنمو من خلال ألعاب الذكاء، ومن خلال الأنشطة الإيجابية، مثل القراءة، أما مع الأنشطة السلبية مثل مشاهدة التلفاز، فإنها تفقد المحفز، وتبقى دون نمو ملحوظ.","p":["الرسالة هي: النصح بالإعراض عن التفكير في الذكاء الموروث والكف عن تقويم الأبناء والتعامل معهم بناء على ما نعتقده من وجوده لديهم"],"items":[{"h":"دراسة الفئران","x":"وجدت إحدى الباحثات أن خلايا قشرة الدماغ تتبدل بالخبرة، وأن الفئران في البيئة الثرية يزداد حجم أدمغتها وتنشأ بين خلاياها روابط جديدة."},{"h":"ما نحرص عليه","x":"الحوار مع الأطفال، وتشجيعهم على القراءة، وزيارة المكتبات والمعارض والمتاحف، وتوفير ألعاب الذكاء."}]},{"t":"القراءة أولوية تربوية","pg":20,"key":"القراءة هي أقوى وسائل النمو الفكري حيوية، ولهذا فإننا في حاجة إلى أن نجعلها في أعلى سلم أولوياتنا التربوية والتعليمية","p":["أن الأطفال المميزين بشكل خاص يقضون في القراءة أربعة أمثال الوقت الذي يقضيه غيرهم من الأطفال فيها","إننا إذا بذلنا جهداً جيداً في تعويد الصغار القراءة، فإنهم سيفضلونها على أي نشاط آخر طيلة حياتهم"],"items":[{"h":"دراسة جامعة إلينوي","x":"على طلاب الصف الخامس: المتفوقون الذين يحصلون على 90% يقرؤون نحو عشرين دقيقة يومياً، ومن يحصلون على 50% يقرؤون ست دقائق فقط."},{"h":"التلفاز","x":"العائلات الناجحة في إحدى الدراسات تشاهده ساعتين وربعاً يومياً، أي أقل من ثلث متوسط عامة الأسر."},{"h":"يوم بلا تلفاز","x":"بعض الأسر لا تفتح التلفاز يوماً في الأسبوع لتكسر حدة الإدمان عليه."}]},{"t":"نصائح لتعويد الطفل القراءة","pg":21,"key":"لكن تجنب في كل الأحوال إجبارهم على قراءة شيء لا يحبونه، حيث إن إكراههم على ذلك قد يكون سبباً في عزوفهم الدائم عن قراءة أي شيء.","p":[],"items":[{"h":"المكتبة العامة","x":"اصطحب الأطفال إليها مرتين في الشهر ودعهم يختارون، ووجه اختيارهم بلطف."},{"h":"المكتبة المنزلية","x":"يشارك أفراد الأسرة في تأسيسها، وتضم المراجع الأساسية في التفسير والحديث والفقه والسيرة والتاريخ واللغة والأدب."},{"h":"القراءة له قبل أن يقرأ","x":"نقرأ له من سن الثالثة القصص اللطيفة ونشرحها، لنؤسس علاقته بالكتاب."},{"h":"الحديث عما قرأ","x":"نسأله عن اسم المؤلف ومحور القصة وأشخاصها، ونربط المضمون بالإيمان والقيم."},{"h":"جلسات أسبوعية","x":"حين يكبر الأبناء تعقد الأسرة جلسات يتحدثون فيها عن الكتب التي قرؤوها وأجمل ما سجلوه منها."}]}],"quiz":[{"q":"متى يجد العقل نفسه عاجزاً عن التفكير في قضية ما بحسب الكتاب؟","o":["إذا افتقر إلى المعلومات والأفكار عنها","إذا ضعف الذكاء الموروث لدى صاحبه","إذا تراكمت المعلومات حولها تراكماً كبيراً","إذا كان حجم الدماغ صغيراً نسبياً"],"why":"كذلك العقل يجد نفسه عاجزاً عن التفكير في أمور لا يملك معلومات وأفكاراً عنها.","pg":15},{"q":"طفل في الخامسة يكثر سؤال أبيه: لماذا وكيف ومن أين. كيف يفسر الكتاب ذلك؟","o":["هو في مرحلة سماها باحث مرحلة التساؤل","هو يحاول جذب انتباه من حوله بكثرة الكلام","هو يعاني نقصاً في ذكائه الفطري","هو يقلد الكبار حين يسمع أحاديثهم"],"why":"وقد أطلق أحد الباحثين على هذه المرحلة اسم (مرحلة التساؤل) حيث تدل بعض الدراسات على أن ما بين (10% إلى 15%) من حديث الطفل في هذه المرحلة يكون عبارة عن أسئلة.","pg":16},{"q":"ما الرسالة التي يستخلصها المؤلف من دراسات تأثر الدماغ بالبيئة المحفزة؟","o":["إثراء البيئة لا الانشغال بالذكاء الموروث","تصنيف الأبناء مبكراً بحسب ما لديهم من ذكاء","الاكتفاء بالمدرسة في تنمية الذكاء","تأجيل التدريب حتى يكتمل نمو الدماغ"],"why":"الرسالة هي: النصح بالإعراض عن التفكير في الذكاء الموروث والكف عن تقويم الأبناء والتعامل معهم بناء على ما نعتقده من وجوده لديهم","pg":18},{"q":"ماذا وجدت دراسة جامعة إلينوي عن عادات القراءة لدى الأطفال المميزين؟","o":["يقضون فيها أربعة أمثال وقت غيرهم","يقضون فيها ضعف وقت غيرهم فقط","يقرؤون المقررات أكثر من غيرهم","يقرؤون ساعة كاملة كل ليلة قبل النوم"],"why":"أن الأطفال المميزين بشكل خاص يقضون في القراءة أربعة أمثال الوقت الذي يقضيه غيرهم من الأطفال فيها","pg":20},{"q":"اخترت لابنك كتاباً فرفض قراءته. ما الذي ينصح به الكتاب؟","o":["ألا تجبره، وأن تدعه يختار ما يحب","أن تلزمه بإتمامه حتى يعتاد الصبر","أن تمنع عنه التلفاز حتى يقرأه","أن تؤجل القراءة حتى يبلغ الثانوية"],"why":"لكن تجنب في كل الأحوال إجبارهم على قراءة شيء لا يحبونه، حيث إن إكراههم على ذلك قد يكون سبباً في عزوفهم الدائم عن قراءة أي شيء.","pg":21}],"scene":{"t":"إدمان الشاشة","x":"لاحظت أن أبناءك يقضون ساعات طويلة كل يوم أمام التلفاز، ويضيقون بأي اقتراح للقراءة.","opts":["تخصص يوماً في الأسبوع لا يفتح فيه التلفاز، وتقدم القراءة بديلاً محبباً","تترك الأمر لأن التلفاز يعلمهم كما تعلمهم الكتب","تفرض عليهم ساعتين من القراءة يومياً مهما كانت رغبتهم"],"why":"وبعض الأسر أخذت على عاتقها عدم فتح التلفاز يوماً في الأسبوع كي تكسر حدة الإدمان عليه لدى الصغار.","pg":21},"rel":[{"b":"read","ci":7,"t":"القراءة المحورية"},{"b":"kids","ci":8,"t":"الخجل"}]},{"k":"c2","t":"وعي الطفل بذاته","q":"كيف نساعد الطفل على معرفة نفسه وتقبلها وتصحيح أخطائه؟","essence":"اعرف نفسك، اقبلها، وانقد خطأك دون أن تدينها","kw":["الذات","المحدودية","النقد الذاتي"],"sections":[{"t":"تكوّن الذات والمشاركة","pg":28,"key":"إن معرفة الإنسان بذاته لا تكتمل أبداً، فهناك دائماً شيء غامض أو مشكوك فيه","p":["إن التفاعل على هذا النحو هو الذي يرفع سوية فهم الأطفال لذواتهم وإمكاناتهم","دعونا نشجع الأطفال على التعبير عن أنفسهم وعن احتياجاتهم، ودعونا نتيح لهم فرصة للاختيار في كل شؤونهم، فإذا اختاروا احترمنا اختياراتهم."],"items":[{"h":"التعرف إلى الذات","x":"يتم عبر التفاعل مع الأبوين والإخوة والجيران والزملاء، والطفل يتخذ من أبويه مثلاً أعلى ويقلده."},{"h":"ما يعين المربي","x":"إشراك الأطفال في المناقشات العائلية، والتدريس الحواري، والسماح لهم باتخاذ بعض القرارات الصغيرة."}]},{"t":"الطفل عبد لله وقبوله ذاته","pg":29,"key":"أول ما ينبغي ترسيخه في عقل الطفل، هو أنه أحد مخلوقات الله","p":["المهم في نظرنا نحن المسلمين، ليس نوعية الابتلاء، وإنما النجاح في الابتلاء"],"items":[{"h":"حتى سن العاشرة","x":"يستمر العمل على ترسيخ معنى العبودية لله حتى نهاية الطفولة المتوسطة، ثم يكون التذكير بحسب الحاجة."},{"h":"التشابه في الأصول","x":"الناس متشابهون في الأمور الرئيسية ويختلفون في الفرعية، كلون العيون وحجم الآذان."},{"h":"اختلاف الأوضاع طبيعي","x":"أن يولد طفل في الريف وآخر في المدينة، وأن يكون بعضهم غنياً وبعضهم فقيراً، أمر طبيعي لا يجعل أسرة مركزية وأخرى هامشية."},{"h":"لا شيء يحقق السعادة بمفرده","x":"المال وحده لا يحقق السعادة، والنقص في شيء لا يسبب الشقاء بمفرده."}]},{"t":"محدودية الإنسان وإمكاناته","pg":32,"key":"الإنسان محدود وزائل وضعيف.. نعم لكنه ليس عاجزاً ولا قليلاً","p":["إن هناك مسافة أبدية بين ما نفعله، وبين ما يمكن أن نفعله"],"items":[{"h":"فائدة الإحساس بالمحدودية","x":"يشعر الصغير بالعبودية والضعف أمام الخالق فيطلب منه العون، ويصبح أقرب إلى الواقعية."},{"h":"إمكان التحسن","x":"نقول للطفل: ترتيبك الخامس ويمكنك أن تكون الرابع، ويمكنك أن تحسن تعاملك مع أساتذتك وإخوتك."}]},{"t":"العقل والعاطفة والخطأ","pg":35,"key":"إن الشيء الذي علينا أن نطلبه من الصغار، ونطلبه من أنفسنا أيضاً، هو إدانة الخطأ، وليس إدانة الشخصية..","p":["إن قدرة الطفل على ضبط عواطفه محدودة، مما يجعل وقوعه في الكذب سهلاً، كما يجعل اختلاط الحقيقة بالخيال لديه أمراً وارداً."],"items":[{"h":"مراجعة الكلام غير الواقعي","x":"لا نسكت حين يتكلم الطفل كلاماً غير واقعي، بل نراجعه وننحو به نحو الصدق وتحري الحق."},{"h":"تعميم الخطأ","x":"من الخطأ أن نعمم زلة واحدة على كل الشخصية، كقول بعض الآباء لابنه: لا خير فيك."},{"h":"نقاط القوة والضعف","x":"على المربي أن يذكّر الطفل بنقاط قوته ويساعده على صقلها، ويعينه على تجاوز ضعفه."}]},{"t":"النقد الذاتي في الأسرة","pg":38,"key":"تحتاج الأسرة كي تشجع صغارها على الاعتراف بالخطأ إلى إرساء تقاليد، تجعل من السهل على أي واحد من أفرادها أن يعترف بخطئه، وأن يعتذر عنه أيضاً","p":["ينبغي أن يعرف الطفل بأنه إذا صدق في حديثه مع أهله، وروى لهم الأحداث كما وقعت، فإن العقوبة ستكون أخف من العقوبة التي ستناله إذا كذب"],"items":[{"h":"كلمات الاعتذار","x":"تعويد الكبار استخدام: عفواً، آسف، لم أنتبه، لم أكن أعرف، أنا مستعد لإصلاح ما أفسدته."},{"h":"المصارحة","x":"يصارح الأبوان الأبناء ويحدثانهم في شأن الأسرة، ويعودانهم الحديث عن مشكلاتهم."},{"h":"بعد الخطأ","x":"نشعر الطفل بخطئه، ونجلس معه لنفكر في حل، ثم نستخلص العبرة ونأخذ الاحتياطات حتى لا يتكرر."}]}],"quiz":[{"q":"أي الأساليب يذكر الكتاب أنه يرفع سوية فهم الأطفال لذواتهم؟","o":["إشراكهم في النقاش والقرارات الصغيرة","حمايتهم من الوقوع في الأخطاء قبل حدوثها","تلقينهم صفاتهم بوضوح وتكرار دائم","مقارنتهم الدائمة بأقرانهم المتفوقين"],"why":"إن التفاعل على هذا النحو هو الذي يرفع سوية فهم الأطفال لذواتهم وإمكاناتهم","pg":28},{"q":"عاد ابنك حزيناً لأن زميله أغنى منه. ما المعنى الذي يقترح الكتاب ترسيخه؟","o":["أن العبرة بالنجاح في الابتلاء لا بنوعه","أن المال يحقق السعادة لمن يحسن جمعه وحفظه","أن الفقر عيب ينبغي ستره عن الناس","أن الأسرة الغنية هي الأسرة المركزية"],"why":"المهم في نظرنا نحن المسلمين، ليس نوعية الابتلاء، وإنما النجاح في الابتلاء","pg":30},{"q":"لماذا لا يكتفي المربي بالشرح النظري حين يوصل معنى ما إلى الصغار؟","o":["لضعف قدرتهم على فهم المعاني المجردة","لأن الأمثلة البعيدة تثير خيالهم الجامح","لأنهم يرفضون الكلام النظري عناداً","لأن الأمثلة تغني عن محاورتهم ونقاشهم"],"why":"علينا ألا نكتفي بالشرح النظري لأي (مفهوم) نريد إيصاله للصغار بسبب ضعف قدرتهم على فهم المعاني المجردة","pg":31},{"q":"أضاع ابنك المراهق نقوداً أعطيته إياها. أي العبارات أقرب إلى منهج الكتاب؟","o":["ما فعلته خطأ، ويمكنك تداركه","لا خير فيك، ولا مستقبل لك","أنت مهمل في كل ما تفعله","لن أثق بك في أي شيء بعد اليوم"],"why":"إن الشيء الذي علينا أن نطلبه من الصغار، ونطلبه من أنفسنا أيضاً، هو إدانة الخطأ، وليس إدانة الشخصية..","pg":36},{"q":"ما الذي يقترحه الكتاب ليصدق الطفل أهله بدل أن يخفي ما وقع منه؟","o":["أن تكون عقوبة الصادق أخف من عقوبة الكاذب","أن تتساوى العقوبة في حالي الصدق والكذب","أن يعاقب فوراً قبل أن يسمع أحد روايته","أن يعفى من المحاسبة مهما كان ذنبه كبيراً"],"why":"ينبغي أن يعرف الطفل بأنه إذا صدق في حديثه مع أهله، وروى لهم الأحداث كما وقعت، فإن العقوبة ستكون أخف من العقوبة التي ستناله إذا كذب","pg":39}],"scene":{"t":"الورطة","x":"جاءك ابنك مرتبكاً يخبرك أنه كسر جهازاً لأخيه أثناء اللعب، وهو ينتظر رد فعلك.","opts":["تشعره بأنه أخطأ، ثم تجلس معه لتفكرا في حل وتستخلصا العبرة","تبدأ حملة قاسية من التقريع حتى لا يعود إلى مثلها","تتجاهل الأمر تماماً حتى لا يحزن"],"why":"وعلينا ثانياً عوضاً عن اللوم أن نُشعر الطفل بأنه أخطأ وأساء، ثم نجلس معه لنفكر في إيجاد حل للورطة التي وجد نفسه فيها","pg":39}},{"k":"c3","t":"مبادئ حياتية عامة (1)","q":"ما المبادئ التي تجعل الطفل يفهم حدود المعرفة والطاقة والرغبة؟","essence":"معرفتنا قليلة، وطاقتنا محدودة، ولكل شيء ثمن","kw":["المحدودية","الثمن","تعدد الزوايا"],"sections":[{"t":"مهما عرفنا فيظل ما نعرفه قليلاً","pg":46,"key":"كم هو جميل أن نرى النهايات ونحن ما زلنا في البدايات","p":["ما دمنا لن نستطيع تعلم كل شيء، فإن علينا إذن أن نتعلم ما هو أعظم أهمية وأكثر إلحاحاً."],"items":[{"h":"طرح الأسئلة","x":"نسأل طفل العاشرة عن كتاب في يده: كم مرة طبع، وكم شخصاً قرأه واستفاد منه، فيكتشف أن أكثرها لا يعرف جوابه."},{"h":"الموقف الموضوعي","x":"التواضع لله والاعتراف بضعف علمنا، وعدم ادعاء ما لا نعلمه، وبذل الجهد لتحصيل العلم النافع."}]},{"t":"لكل شيء طاقة على التحمل","pg":48,"key":"كل مخلوقات الله مهما كانت عظيمة وقوية تظل محدودة، ولها إمكانات محدودة","p":["الدرس هو: أن على العاقل أن يحرص على عدم وضع نفسه في مواقف صعبة ومحرجة حتى لا يجد نفسه ضعيفاً، مما يجعله يستهين بالوقوع في الخطأ","أما الدرس الذي نستفيده نحن الكبار من مسألة محدودية طاقة الضمير على الردع، فهو عدم الضغط على الصغار، وعدم تشديد العقوبات عليهم إلى درجة تجعل (الضمير) يتوقف عن عمله"],"items":[{"h":"الحديد","x":"للحديد في أعمدة البناء طاقة محدودة، فإذا حُمّل فوق طاقته انحنى."},{"h":"الضمير","x":"للوازع الداخلي طاقة محدودة، فيضعف أمام ضغوط الخسائر والعقوبات وأمام المغريات."}]},{"t":"لكل شيء ثمن","pg":51,"key":"ليس هناك وضعية من الوضعيات، تحوز كل الميزات، كما أنه ليس هناك وضعية، فيها كل العيوب والسلبيات","p":["الخلاصة هي: أن الصغار والكبار على حد سواء، لا يستطيعون الحصول على كل شيء، ولهذا فإن علينا أن نعرف ماذا نأخذ، وبماذا نضحي"],"items":[{"h":"الراحة","x":"ركوب السيارة للمسافات القصيرة ثمنه الترهل، والاعتماد على الخدم ثمنه الشعور بالعجز."},{"h":"اللذة","x":"إشباع شهوة الطعام بلا قيود ثمنه السمنة وأمراضها."},{"h":"الحرية","x":"من حق الطالب أن يختار ما يقرأ، لكن لهذه الحرية ثمناً قد يكون الرسوب أو الدرجات المتدنية."}]},{"t":"لا حدود لإشباع الرغبات","pg":53,"key":"إن ما في الأرض من خيرات كاف لسد حاجات كل الناس لكنه ليس كافياً لتلبية رغبات رجل واحد","p":["إن الطفل ابن العاشرة يستطيع فهم هذا المبدأ بسهولة من خلال تذكيره ببعض الأشياء التي كان يظن أنه إذا حصل عليها، فإنه لن يطلب أي شيء آخر"],"items":[{"h":"طموحات واسعة","x":"الإنسان لا يتوقف عند حد مهما أعطي، والقرآن والسنة عبرا عن ذلك."},{"h":"الاعتدال","x":"نلقن الأطفال أن الأشياء التي يتطلعون إليها ستبدو أقل إمتاعاً حين يحصلون عليها، فيتناولون رغباتهم باعتدال وبطريقة مشروعة."}]},{"t":"معظم الأشياء قابل لأن يرى بطرق مختلفة","pg":54,"key":"الناس لا ينظرون دائماً إلى الأشياء والأحداث بطريقة موحدة أو مجردة وإنما ينظرون إليها من زوايا مختلفة ومنظورات متباينة","p":["كما أن استيعاب هذا المبدأ يجعل الطفل أكثر تسامحاً تجاه المخالفين.","إن نصف هذا الكأس فارغ، فنكون من جملة الذين يشكون، ويتأففون، ويمكن أن نقول: إن نصفه مملوء، فنكون ممن يفرح بالقليل، ويحاول تكثيره."],"items":[{"h":"قول عمر بن الخطاب","x":"ما أصيب بمصيبة إلا حمد الله على ثلاث: أنها لم تكن في دينه، وأنها لم تكن أكبر مما وقع، والثواب الذي يرجوه."},{"h":"مصائب قوم عند قوم فوائد","x":"حادث السيارتين أذى لصاحبيهما ورزق لمن يتولى إصلاحهما."},{"h":"المؤمن والابتلاء","x":"يرى المسلم النعمة والمصيبة كلتيهما ابتلاء من الله، فيشكر في الأولى ويصبر في الثانية."}]}],"quiz":[{"q":"ما الموقف الذي يعلمه الكتاب للأطفال تجاه قلة ما نعرفه؟","o":["التواضع وعدم ادعاء معرفة ما نجهله","الكف عن طلب العلم لأنه لا يحاط به","الاكتفاء بما في الكتب المدرسية","التظاهر بالمعرفة حفظاً لهيبة المربي"],"why":"عدم ادعاء معرفة ما لا نعلمه.","pg":48},{"q":"قال ابنك عن كأس فيه ماء إلى منتصفه: نصفه فارغ. ما الذي يريد الكتاب أن نعلمه إياه؟","o":["أن نفرح بالقليل ونحاول تكثيره","أن الشكوى حق لكل من يرى نقصاً","أن نرى الأمور كما هي دون تأويل","أن نتجاهل النقص حتى لا نحزن"],"why":"ويمكن أن نقول: إن نصفه مملوء، فنكون ممن يفرح بالقليل، ويحاول تكثيره.","pg":58},{"q":"يريد ابنك أن يقرأ ما يحب فقط ويهمل مقرراته. أي مبدأ يوضحه الكتاب في هذا المثال؟","o":["أن للحرية ثمناً قد يكون الرسوب","أن الرغبات لا حدود لإشباعها","أن لكل شيء طاقة محدودة على التحمل","أن الصدمات تكون كبيرة ثم تصغر"],"why":"لكن لممارسة هذه الحرية ثمن، يجب أن يدفعه عن طيب خاطر، وهو الرسوب أو النجاح بدرجات متدنية.","pg":52},{"q":"بأي طريقة يستطيع ابن العاشرة أن يفهم أن الرغبات لا حدود لها؟","o":["بتذكيره بأشياء ظن أنها تغنيه عن غيرها","بحرمانه من كل ما يطلبه مدة طويلة متصلة","بشراء كل ما يريده حتى يمل منه ويتركه","بإقناعه أن الرغبة كلها مذمومة شرعاً"],"why":"إن الطفل ابن العاشرة يستطيع فهم هذا المبدأ بسهولة من خلال تذكيره ببعض الأشياء التي كان يظن أنه إذا حصل عليها، فإنه لن يطلب أي شيء آخر","pg":54},{"q":"ما الثمرة التي يذكرها الكتاب لفهم الطفل أن الأحداث تُرى من زوايا متباينة؟","o":["أن يصبح أكثر تسامحاً مع المخالفين","أن يشك في كل ما يسمعه من الكبار","أن يتمسك برأيه دائماً لأن الحقائق نسبية","أن يتجنب النقاش لكثرة الآراء المختلفة"],"why":"كما أن استيعاب هذا المبدأ يجعل الطفل أكثر تسامحاً تجاه المخالفين.","pg":55}],"scene":{"t":"كذب خوفاً","x":"اكتشفت أن ابنك كذب في أمر بسيط، ثم تبين أنه خاف من عقوبة قاسية نالها في مرة سابقة.","opts":["تخفف من شدة العقوبات حتى لا يتوقف ضميره عن عمله","تضاعف العقوبة حتى يتعلم ألا يكذب أبداً","تترك الأمر دون أي حديث معه"],"why":"أما الدرس الذي نستفيده نحن الكبار من مسألة محدودية طاقة الضمير على الردع، فهو عدم الضغط على الصغار، وعدم تشديد العقوبات عليهم إلى درجة تجعل (الضمير) يتوقف عن عمله","pg":50}},{"k":"c4","t":"مبادئ حياتية عامة (2)","q":"كيف نعلم الطفل مواجهة الصدمات والنقص، وقيمة العمل والتغيير؟","essence":"المصيبة تصغر، والعمل يغني، والتغيير يبدأ بالنفس","kw":["الصدمات","العمل","التغيير"],"sections":[{"t":"صدمات الحياة تكون كبيرة ثم تصغر","pg":58,"key":"وقد عبروا عن هذه الحقيقة بقولهم: (كل شيء يكون صغيراً، ثم يكبر إلا المصيبة فإنها تكون كبيرة ثم تصغر)","p":["فالألم الذي نواجهه في اللحظة الأولى لوقوع الضراء، يكون في الساعة الثانية أقل، وفي الساعة الثالثة أقل وأقل"],"items":[{"h":"الصبر عند الصدمة الأولى","x":"التماسك المطلوب يكون في لحظة وقوع المصيبة، كما في الحديث الشريف."},{"h":"حاجة الأطفال","x":"الأطفال لضعف خبرتهم أحوج من الكبار إلى معرفة هذا المبدأ، فبعضهم يقول بعد الرسوب: انتهى كل شيء."},{"h":"دراسة المشلولين","x":"وجدت إحدى الدراسات أن سعادة مشلولي الأطراف الأربعة لا تختلف كثيراً عن سعادة العاديين."}]},{"t":"لا حلول كاملة في وسط غير كامل","pg":60,"key":"الرسالة التي نود إيصالها إلى الأطفال هي: أن على الواحد منا أن يوطّن نفسه للحلول المنقوصة والإنجازات المحدودة، والظروف المعاكسة","p":["إذا كانت أخيلتنا جامحة، وإراداتنا طليقة، فإن قدراتنا محدودة"],"items":[{"h":"طموحات واسعة","x":"نريد أن نحصل على كل شيء، وأن نتخلص من المشكلة كأنها لم تكن."},{"h":"ظروف خارج السيطرة","x":"انقطاع الكهرباء في الجو الحار، أو تغير أحوال الجامعة على الطالب، أمثلة على ظروف لا نصنعها."},{"h":"مع الطفل المتعثر","x":"نتفهم أسباب رسوبه أو ضياع ماله، ونلتمس له العذر، ونرفع معنوياته."}]},{"t":"لا شيء يغني عن العمل","pg":62,"key":"إن السبب الأساسي للنجاح في هذه الحياة، يكمن في الجهد الذي نبذله","p":["العمل ينقل الأطفال، كما ينقل الكبار من مرحلة التطلع والاشتهاء إلى مرحلة الممارسة","إن التقاعس والكسل والإهمال، تشكل قواعد أساسية للفقر والإخفاق والتهميش"],"items":[{"h":"العمل متعة","x":"يشعر صاحبه بالإنجاز والثقة، ونشرح للطفل أن الناس يقدّرون جهد الأطفال في العمل النافع."},{"h":"علاج الفراغ","x":"العمل يخلصنا من الشعور بالفراغ، وهو من أعداء السعادة، وكثير من السلوكيات السيئة تنتج عنه."},{"h":"دون إنكار الذكاء","x":"لا ننكر تأثير الذكاء والنبوغ، لكن نركز على أهمية العمل في التقدم."},{"h":"الأعمال الشاقة","x":"ندرب الأبناء على الواجبات المنزلية ومساعدة الآباء، ونشعرهم في المدارس بجدية الدراسة."}]},{"t":"تغيير النفوس والسلوكات هو أساس كل تغيير","pg":66,"key":"فكلمة (أنت) تشكل أساس نظر الطفل لمن حوله، على حين أن الراشد يكون الأساس لديه هو كلمة (أنا) و(نحن).","p":["مهمتنا نحن المربين أن نغرس في عقول أبنائنا ونفوسهم قيمة تحمل المسؤولية تجاه غيرهم"],"items":[{"h":"بعد فكرة التغيير","x":"الأطفال تكون فكرة التغيير بعيدة عنهم لاستغراق الأشياء المحسوسة وعيهم، فيلقون التبعات على غيرهم."},{"h":"أمثلة عملية","x":"تقبيل يد الأبوين، والسماح لأبناء الجيران باللعب بألعابه، وإطفاء الأنوار، والاقتصاد في الماء، وعدم الكتابة على الجدران أو إلقاء القمامة في الطرق."}]}],"quiz":[{"q":"رسب ابن جيرانك في الامتحان فقال: انتهى كل شيء. أي مبدأ يحتاج إلى فهمه؟","o":["أن صدمات الحياة تكون كبيرة ثم تصغر","أن لا حدود لإشباع الرغبات البشرية","أن لكل شيء ثمناً لا بد من دفعه كاملاً","أن رضا الناس غاية لا تدرك أبداً"],"why":"وقد عبروا عن هذه الحقيقة بقولهم: (كل شيء يكون صغيراً، ثم يكبر إلا المصيبة فإنها تكون كبيرة ثم تصغر)","pg":59},{"q":"ماذا أظهرت الدراسة التي أجريت على مشلولي الأطراف الأربعة؟","o":["أن سعادتهم لا تختلف كثيراً عن العاديين","أن سعادتهم انعدمت مدة عشرين سنة","أن شعورهم بالرضا زاد مع تقدم السن","أن الإعاقة تسلب صاحبها الأمل والرضا كلياً"],"why":"أن ما يشعرون به من السعادة، لا يختلف كثيراً عما يشعر به الأشخاص العاديون","pg":60},{"q":"على أي شيء يريد الكتاب أن يوطن الطفل نفسه، ما دامت قدراتنا محدودة؟","o":["الإنجازات المحدودة والظروف المعاكسة","الكمال التام في كل ما يقوم به من أعمال","الهرب من المشكلات قبل أن تقع عليه","الاعتماد على غيره في تجاوز أزماته"],"why":"الرسالة التي نود إيصالها إلى الأطفال هي: أن على الواحد منا أن يوطّن نفسه للحلول المنقوصة والإنجازات المحدودة، والظروف المعاكسة","pg":61},{"q":"يقضي ابنك وقته في أمنيات وردية عن مستقبله دون أن يفعل شيئاً. ماذا يقرر الكتاب؟","o":["العمل ينقله من التطلع إلى الممارسة","الأحلام وحدها تكشف له مواهبه الكامنة","الخيال الجامح يقربه من الواقع","التمني يغنيه عن تجربة الأشياء"],"why":"العمل ينقل الأطفال، كما ينقل الكبار من مرحلة التطلع والاشتهاء إلى مرحلة الممارسة","pg":65},{"q":"عند شرح أثر الجهد في النجاح للطفل، ما الذي يحذر الكتاب منه؟","o":["إنكار أثر الذكاء والنبوغ","ربط النجاح بالعمل والحركة","ذكر نماذج لأشخاص مجتهدين","تشجيع الطفل على تنظيم وقته"],"why":"لا يصح ونحن نشرح للطفل هذه الحقيقة أن ننكر ما للذكاء والنبوغ من تأثير مهم في النجاح","pg":64}],"scene":{"t":"بعد الرسوب","x":"رسب ابنك في إحدى السنوات، وبدأ بعض الأقارب يصفونه بالكسل والإهمال أمامه، وثقته بنفسه تضعف.","opts":["تتفهم أسباب ما حدث وتلتمس له عذراً، وترفع معنوياته","تغضب عليه وتعاقبه حتى يشعر بخطورة ما وقع","تقارنه بأقرانه المتفوقين لعله يتحفز"],"why":"إن هذا يتطلب منا أن نتفهم أسباب ما حدث، ونلتمس نوعاً من العذر للطفل، كما يتطلب منا أن نرفع معنوياته، وأن نساعده على تجديد الثقة بنفسه وعلى تجاوز الأزمة.","pg":62}},{"k":"c5","t":"الطفل المفكر","q":"ما خصائص الطفل المفكر، وكيف ننميها؟","essence":"الطفل المفكر يرحب بالجديد ويتروى ويستقل","kw":["التفكير","الغموض","الاستقلال"],"sections":[{"t":"التفكير وأهمية التدريب عليه","pg":76,"key":"إن التفكير يشكل السلوك الإنساني الأشد تعقيداً، وهو عمل شاق جداً، ولهذا فإننا نتجنبه، ونبتعد عنه قدر الإمكان.","p":["إن بعض الدراسات يشير إلى أن الأطفال بدءاً من سن التاسعة، يستطيعون تقريباً مناقشة أي مشكلة إذا تلقوا التدريب المناسب.","إن أفضل ما يقدمه الكبار للصغار، هو مساعدتهم على إثارة عقولهم، ليس عن طريق القصص والحكايات والمعارف الصحيحة فحسب، وإنما عن طريق تدريبهم على التأمل وطرح الأسئلة، وتقديم المقترحات"],"items":[{"h":"تحول العصر","x":"دور الجهد العضلي يتراجع لمصلحة الجهد الذهني والمعرفي، فالنفوذ اليوم لمن يعرفون أكثر."},{"h":"تجربة المدرسة الريفية","x":"مجموعتان من أطفال العاشرة ناقشتا اقتراح منح التلاميذ أجراً أسبوعياً: المدربة رفضته بنقاش عقلاني، وغير المدربة رأت التلاميذ أحق بالأجر من المعلمين."},{"h":"إرث الانحطاط","x":"مهمة الصغار في التربية الموروثة اختزان أفكار الكبار، فيكفون عن التفكير وتضمر قدراتهم."}]},{"t":"الترحيب بالجديد","pg":80,"key":"فإن الطفل المفكر يبدي اهتماماً كبيراً به، ويحاول استيعابه والاستفادة منه، على حين أن الطفل غير المفكر أو الطفل العادي يخاف من الجديد","p":[],"items":[{"h":"في الفصل","x":"في فصل من ثلاثين طالباً يتفاعل أربعة أو خمسة بقوة مع الأفكار الجديدة."},{"h":"ليس كل جديد جيداً","x":"الجديد قد يكون جيداً وقد يكون سيئاً، والمقصود تشجيع المربين على بلورة هذه السمة."}]},{"t":"التسامح مع الغموض","pg":81,"key":"فالطبيعة البشرية، تميل إلى السهل الواضح، وتنفر من الصعب الغامض","p":["ومن هنا فإن علينا تشجيع الطلاب على قراءة الكتب التي تتحداهم"],"items":[{"h":"تدريب على النماذج الغامضة","x":"يشرح المعلم خصائص الإنسان العاطفي، ثم يطلب من الطلاب أن يبلوروا نماذج كالشحيح والجبان والمتهور والقلق."},{"h":"الكتب السهلة","x":"معظم الأبناء يميلون إلى الكتب السهلة التي لا تحدث أي اهتزاز في خبراتهم."}]},{"t":"التروي والأناة","pg":82,"key":"من أعدى أعداء التفكير المثمر العجلة والرغبة في الوصول إلى نتائج سريعة","p":["إن الحل أو الشيء المرغوب الذي نبحث عنه، لا يرفع الأقنعة عن وجهه من أول محاولة"],"items":[{"h":"المعلم القدوة","x":"يفكر بصوت مسموع، ويقول لطلابه: ما زلنا في مرحلة جمع البيانات، من لديه اقتراح إضافي؟"},{"h":"التجريب","x":"الأفكار الجيدة تأتي بعد استنفاد الأفكار الرديئة، والمدارس مسؤولة عن الورش والمختبرات وجلسات العصف الذهني."}]},{"t":"الميل إلى الاستقلال","pg":84,"key":"إن الأسرة تستطيع أن تدعم ميول الطفل إلى الاستقلال من خلال السماح له بالاعتراض على الأمور التي لا تعجبه، ومن خلال إجابته على أسئلته وتشجيعه على مناقشة الأفكار التي يسمعها","p":["وحين يقدم الطفل بعض الآراء الفجة والمرفوضة، فإنها لا توبخه، وإنما تشرح له بلطف وجه الصواب فيما يقول"],"items":[{"h":"مخطوطة فريدة","x":"كل واحد منا فريد في عقله ومشاعره، لكن قسوة التربية تجعلنا متشابهين."},{"h":"دور المدرسة","x":"عرض وجهات النظر المختلفة في القضية الواحدة، وتحفيز الطالب على الرجوع إلى المصادر وإبداء رأيه."}]},{"t":"حب اللعب والمرح","pg":86,"key":"إن الطفل الذي يحب المرح، ويميل إلى اللعب مع الأصدقاء والزملاء، يكون في وضعية نفسية أفضل من الطفل الهادئ أو المنعزل أو الذي يُظهر قدراً زائداً من الجدية.","p":["فاللعب والمرح والتسلي والضحك أمور إيجابية وذات فوائد كبرى لعقل الطفل وروحه إذا ظلت في حدود الاعتدال."],"items":[{"h":"فوائد اللعب","x":"يحسن المحاكمة العقلية، ويعلم احترام القواعد المشتركة وامتصاص أخطاء الآخرين بروح رياضية."},{"h":"نظرة خاطئة","x":"بعض المدرسين يرون الطفل كثير الحركة مفتقراً إلى الجدية، وهذا شيء خاطئ."}]}],"quiz":[{"q":"في تجربة اقتراح أجر أسبوعي للتلاميذ، ماذا قالت المجموعة التي لم تتلق تدريباً؟","o":["التلاميذ أحق بالأجر من المعلمين","الأجر لا يوجد مصدر يستطيع دفعه","الأطفال لا يستحقون أي أموال","المدرسة لا تحتاج إلى حوافز مالية"],"why":"إذا تقاضى المعلمون مالاً، فيتعين أن يتقاضى التلاميذ كذلك، وهذا بسبب أن التلاميذ يبذلون جهداً أكبر من الجهد الذي يبذله المدرسون!","pg":77},{"q":"متى تشير بعض الدراسات إلى أن الطفل يستطيع مناقشة أي مشكلة تقريباً؟","o":["من التاسعة إذا تلقى التدريب المناسب","من السادسة إذا أتقن مهارة القراءة","من الثالثة عشرة بعد اكتمال نموه","من الحادية عشرة دون حاجة إلى أي تدريب"],"why":"إن بعض الدراسات يشير إلى أن الأطفال بدءاً من سن التاسعة، يستطيعون تقريباً مناقشة أي مشكلة إذا تلقوا التدريب المناسب.","pg":77},{"q":"طرح المعلم فكرة لم يسمع بها الطلاب من قبل. كيف يتصرف الطفل المفكر؟","o":["يهتم بها ويحاول استيعابها","يرفضها لأنه يخاف من كل جديد","يقبلها فوراً لأن كل جديد جيد","يقف منها موقف غير المبالي"],"why":"فإن الطفل المفكر يبدي اهتماماً كبيراً به، ويحاول استيعابه والاستفادة منه، على حين أن الطفل غير المفكر أو الطفل العادي يخاف من الجديد","pg":80},{"q":"معلم يقول لطلابه: ما زلنا نجمع البيانات، من لديه اقتراح إضافي؟ أي خصيصة ينميها فيهم؟","o":["التروي والأناة","الترحيب بالجديد","الاستقلال في الرأي","حب اللعب والمرح"],"why":"إنه ينادي في طلابه: إننا ما زلنا في مرحلة جمع البيانات، إن معلوماتنا لم تكتمل","pg":83},{"q":"قدم ابنك رأياً فجاً في نقاش عائلي. كيف تدعم الأسرة ميله إلى الاستقلال؟","o":["تشرح له بلطف وجه الصواب دون توبيخ","تزجره بشدة حتى لا يكرر مثل هذه الآراء","تمنعه من الاعتراض على ما لا يعجبه","تتجاهل كلامه كي لا يتمادى فيه"],"why":"وحين يقدم الطفل بعض الآراء الفجة والمرفوضة، فإنها لا توبخه، وإنما تشرح له بلطف وجه الصواب فيما يقول","pg":85}],"scene":{"t":"مرح في الفصل","x":"أنت معلم، ويحب أحد طلابك المزاح والحركة، وزميلك يرى أن ذلك ينافي الجدية ويطالبك بمنعه تماماً.","opts":["تعد المرح المعتدل نافعاً لعقله وروحه، وتضبطه دون أن تمنعه","تمنع المزاح في الفصل منعاً تاماً حفاظاً على الهيبة","تترك المرح بلا ضابط لأن الطفل يحب اللعب"],"why":"فاللعب والمرح والتسلي والضحك أمور إيجابية وذات فوائد كبرى لعقل الطفل وروحه إذا ظلت في حدود الاعتدال.","pg":87}},{"k":"c6","t":"أنواع التفكير: التفكير الإبداعي","q":"ما مكونات التفكير الإبداعي، وكيف ندرب الطفل عليه؟","essence":"الإبداع طلاقة ومرونة وإحساس بالمشكلات وأصالة","kw":["الطلاقة","المرونة","الأصالة"],"sections":[{"t":"الإبداع والأمان والحرية","pg":91,"key":"يمكن القول: إن التفكير الإبداعي عبارة عن نشاط ذهني منظم، يؤدي إلى نتائج وحلول تتصف بالجدة والأصالة.","p":["إن تدريب الأطفال والشباب على التفكير الإبداعي، يعد بحق مهمة وطنية كبرى، تحتاج إلى استنفار كل الجهود وحشد كل الطاقات.","ونلاحظ في هذا السياق أن الطفل حتى يبدع يحتاج إلى الشعور بشيئين أساسيين، هما الأمان والحرية"],"items":[{"h":"تقسيمات التفكير","x":"يقسم التفكير بحسب الأزواج المتناظرة كالإبداعي والتقاربي، أو بحسب الموضوعية كالعلمي والخرافي."},{"h":"مطلوب الجيل الجديد","x":"مهارات الاتصال والتقويم والتفكير الحاسم وحل المشكلات واتخاذ القرارات، لا القراءة والكتابة والحساب وحدها."},{"h":"شهادة أينشتاين","x":"نقل المؤلف من سيرة أينشتاين أن أساليب التدريس القاسية أفقدته الرغبة في النظر إلى المشكلات مدة عام كامل."}]},{"t":"الطلاقة","pg":94,"key":"الطلاقة مكون أساسي من مكونات التفكير الإبداعي، وهي تعني القدرة الجيدة على التوليد: توليد الأفكار وتوليد الكلمات والجمل والتعبيرات...","p":[],"items":[{"h":"علامة المبدع","x":"من يطلق مصطلحاً جديداً يلقى الاستحسان، أو يقترح ثلاثة حلول لمشكلة عجز أقرانه عن حل واحد لها."},{"h":"الطلاقة الترابطية","x":"يطلق الأب كلمة ويطلب من الصغار كلمات تدل على معناها، ثم ضدها."},{"h":"الطلاقة التعبيرية","x":"يطلب الأب ذكر أكبر عدد من الكلمات المكونة من أربعة حروف دون تكرار."},{"h":"الحكاية بلا عنوان","x":"يحكي الجد أو الأم حكاية صغيرة ويطلب من الصغار وضع عنوان لها."}]},{"t":"المرونة","pg":95,"key":"المرونة مكوّن مهم من مكونات التفكير الإبداعي، وهي تعني رحابة عقل الإنسان في رؤية الأشياء وتفسير الأحداث","p":[],"items":[{"h":"مثال الحجر","x":"حجر بحجم قبضة اليد يستعمل في البناء، وفي زجر كلب، وفي دق مسمار، وفي تثبيت الأوراق، ثم يطلب من الطفل استخدامات أخرى."},{"h":"في البيت والمدرسة","x":"نطلب من الأطفال استخدامات للقلم والمسطرة والكتاب والقدر والكرسي، وتعقد مسابقات لذلك."}]},{"t":"رهافة الإحساس بالمشكلات والأصالة","pg":96,"key":"أما المبدعون، فإنهم يعرفون الأصول التي يجب أن تكون عليها الأشياء، وبالتالي فإنهم يرون المفارقات بين ما هو كائن، وما ينبغي أن يكون","p":["وأنت ترى أن الإحساس بالمشكلات هو أحد أسس (التفكير النقدي) وذلك لأن النقد في الحقيقة هو نوع من أنواع الإبداع.","لكن الأصالة لا تقتصر على الجدّة، وإنما تعنى أيضاً النفع والفائدة"],"items":[{"h":"غير المبدعين","x":"لا يرون كثيراً من المشكلات، يتكيفون معها حتى تصبح المعاناة عادية، أو يرضون بأنصاف الحلول."},{"h":"تجربة الصف السادس","x":"مجموعتان من مدرستين، لكل منهما أربعون دقيقة للحديث بصدق عن ميزات مدرستها وسلبياتها، ثم تدوين مشكلاتها ومناقشتها."},{"h":"صقل الفكرة","x":"دور المبدع غالباً صقل الفكرة أو تحويرها أو الإضافة إليها، لا توليدها من العدم."}]},{"t":"نصائح لتفتيح ذهن الطفل","pg":98,"key":"ولهذا فإن ترحيبنا بكل الأفكار التي يطرحونها، يساعدهم على الإبداع والتجديد.","p":["لأن الإبداع كثيراً ما يكون عبارة عن إدراك للطرق المفتوحة والطرق المغلقة."],"items":[{"h":"المبدعون غرباء","x":"المبدعون قليلون، ويطرحون فروضاً وأفكاراً مختلفة عما لدى السواد الأعظم."},{"h":"مجالسة المبدعين","x":"إن كان في الحي أو الأقارب من يعرف بالعبقرية، فخذ أبناءك إليه."},{"h":"التفكير الموسع","x":"نحث الطفل على تصور كل شيء ممكن الحدوث، كالغنى والفقر والنجاح والرسوب، ثم آثاره."},{"h":"التشبيهات","x":"نطلق تشبيهات بليغة ونطلب من الطفل إكمال تشبيه مثل: النزول إلى النهر للسباحة مثل..."},{"h":"الأحداث المفاجئة","x":"نسأله: لو عدت إلى منزلك وليس معك مفتاح وليس في المنزل أحد، كيف تتصرف؟"}]}],"quiz":[{"q":"يذكر الكتاب أن الطفل يحتاج حتى يبدع إلى الشعور بشيئين أساسيين. ما هما؟","o":["الأمان والحرية","الذكاء والموهبة","المال والرفاهية","الطاعة والانضباط"],"why":"ونلاحظ في هذا السياق أن الطفل حتى يبدع يحتاج إلى الشعور بشيئين أساسيين، هما الأمان والحرية","pg":92},{"q":"يطلب أب من ابنه أكبر عدد من الكلمات المكونة من أربعة حروف دون تكرار. أي قدرة ينميها؟","o":["الطلاقة التعبيرية","المرونة في التفسير","الأصالة في الأفكار","الإحساس بالمشكلات"],"why":"ومن أجل تعزيز (الطلاقة التعبيرية) يمكن أن يطلب الأب من ابنه الصغير أن يذكر أكبر عدد من الكلمات المكوّنة من أربعة حروف","pg":95},{"q":"كيف يتعامل غير المبدعين مع المشكلات القائمة من حولهم؟","o":["يتكيفون معها حتى تصير معاناتهم عادية","يرون المفارقة بين الكائن وما ينبغي","يقترحون لها حلولاً جديدة غير مقتبسة","يحولونها إلى فرص دائمة للتجديد والتطوير"],"why":"الأشخاص غير المبدعين، لا يرون الكثير من المشكلات القائمة، إنهم تارة يتكيفون معها، فتصبح المعاناة شيئاً عادياً في حياتهم","pg":96},{"q":"لماذا يجعل الكتاب الإحساس بالمشكلات أحد أسس التفكير النقدي؟","o":["لأن النقد في حقيقته نوع من الإبداع","لأن الناقد يتصيد العيوب دون أن يرى غيرها","لأن المشكلات لا يراها إلا الكبار","لأن النقد يغني عن اقتراح البدائل"],"why":"وأنت ترى أن الإحساس بالمشكلات هو أحد أسس (التفكير النقدي) وذلك لأن النقد في الحقيقة هو نوع من أنواع الإبداع.","pg":97},{"q":"إلى جانب الجدة، ماذا تعني الأصالة في الأفكار بحسب الكتاب؟","o":["النفع والفائدة","الغرابة والندرة","السرعة والكثرة","القدم والرسوخ"],"why":"لكن الأصالة لا تقتصر على الجدّة، وإنما تعنى أيضاً النفع والفائدة","pg":97}],"scene":{"t":"فكرة غريبة","x":"طرح ابنك على مائدة العشاء فكرة غريبة لحل مشكلة في الحي، فضحك إخوته منها.","opts":["ترحب بفكرته وتناقشها معه، وتطلب من إخوته احترامها","تضحك معهم ثم تبين له أن فكرته غير واقعية","تطلب منه ألا يتكلم إلا فيما يفهمه"],"why":"ولهذا فإن ترحيبنا بكل الأفكار التي يطرحونها، يساعدهم على الإبداع والتجديد.","pg":98}},{"k":"c7","t":"التفكير الإيجابي والتفكير الواقعي","q":"كيف نبني لدى الطفل نظرة متفائلة لا تنفصل عن الواقع؟","essence":"تفاؤل بلا أوهام، وصدق بلا قسوة","kw":["الإيجابية","الواقعية","التعبيرات"],"sections":[{"t":"التفكير الإيجابي والجو الأسري","pg":100,"key":"إن الجو الأسري والتعليمي الإيجابي هو الأساس في كل شيء، ومن المؤسف أننا محتاجون إلى أن نجعل الآباء والمعلمين إيجابيين أولاً","p":["إن الإنسان الإيجابي لا يعتمد على معلومات ومعطيات جديدة في تفكيره، ولا يحاول اكتشاف أمور لم يكن يراها من قبل، وإنما يقوم بإدارة عواطفه والعمل على استخدام اللغة على نحو مشجع ومحفز"],"items":[{"h":"تذكيره بنجاحاته","x":"نذكر الطفل بوقائع تفوقه كالصدق والمثابرة والعطف على إخوته، فيزداد ثقة بنفسه."},{"h":"الخطأ المضاد","x":"بعض الناس يذكّرون أبناءهم بزلاتهم وإخفاقاتهم: أتذكر يوم ضربك فلان؟ وهذا كله خطأ يجب أن يتوقف فوراً."}]},{"t":"الكلمات والتعبيرات","pg":102,"key":"علّم الطفل إذا قلت له: كيف حالك أن يقول: الحمد لله في أفضل حال","p":["إن هذه التعبيرات تُضعف الروح المعنوية لدى الطفل، وتثير لديه مشاعر التذمر واليأس."],"items":[{"h":"الشكوى بلطف","x":"نعلم المريض أن يقول: لدي صداع، بدل المبالغة التي تدفعه إلى استدرار العطف."},{"h":"تعبيرات إيجابية","x":"يمكن أن أعمل كذا، اتركوا لي الفرصة كي أجرب، سأحاول، نقدك مقبول وسأعمل به."},{"h":"تعبيرات سلبية","x":"أنا خائف، لا أمل لي في الحصول على أي شيء، الناس يكرهونني، ليس لي أصدقاء."},{"h":"شكر النعم","x":"نعوّد الأطفال الحمد على وجود الأبوين والإخوة والمدرسة، ونذكّرهم بالمحرومين من ذلك."}]},{"t":"تلمس المستقبل والتطلع إلى المعالي","pg":105,"key":"إذا لم نستطع مساعدة الأطفال على أن يتطلعوا إلى المعالي، فلا أقل من أن نكفّ عن شدهم إلى الوراء.","p":["إن مثل هذه النصائح مدمرة لنفسية الطفل","يجب أن نشرح للأبناء أنه لا يشترط للمرء حتى يكون متميزاً أن يكون متفوقاً في كل سنوات دراسته، أو في جميع المواد"],"items":[{"h":"بعد الرسوب","x":"نقول للطفل: شعورك بالأسى مؤقت، وغداً ستكون أحسن، ولنستعد للامتحانات القادمة."},{"h":"سؤال الأحلام","x":"نسأل ابن السادسة: ماذا تحب أن تكون في المستقبل؟ ونكرر السؤال كلما كبر."},{"h":"تصنيف الصغار","x":"بعض المعلمين والآباء يضعون سقفاً لتطلعات الأبناء، فيزرعون فيهم بذور الشك واليأس."}]},{"t":"التفكير الواقعي","pg":108,"key":"إن بناء تفكير واقعي لدى الناشئة، هي محاولة شاقة ومحفوفة بالمخاطر","p":["لا شك أن الوضع صعب للغاية، لكن مع كل هذا يبقى خيار الصدق والأمانة والمكاشفة، وتقرير الواقع هو الخيار الأفضل."],"items":[{"h":"إخفاء الحقائق","x":"يخفي الأطفال رسوبهم خوفاً من التأنيب، ويخفي الكبار خلافاتهم، فيُفاجأ الصغار بالطلاق أو انهيار الأسرة."},{"h":"التخويف بالخرافة","x":"تخويف الصغار بالجان والعفاريت يدفعهم في طريق التفكير الخرافي."},{"h":"الموازنة","x":"نحتاج إلى موازنة بين التفكير الإيجابي المتفائل والتفكير الواقعي الذي يرى الأوضاع كما هي."}]},{"t":"متى نخبر الطفل وكيف","pg":111,"key":"ليس من الصواب أن نحدّث طفلاً في الثامنة من عمره عن الديون المتراكمة على أبيه","p":["تتوقف مساعدة الأطفال على استيعاب الواقع وعلى التفكير بواقعية على أمر أساسي في التربية، هو التواصل معهم والبحث عن الأوقات الملائمة للتحدث إليهم أكثر وأكثر"],"items":[{"h":"سن المكاشفة","x":"حين يصبح الابن في الثالثة عشرة أو الرابعة عشرة يمكن أن نحدثه عن ذلك ليكون له دور في التخفيف من حدته."},{"h":"الانتقال إلى مدينة جديدة","x":"يشرح الأب لابنه سبب الانتقال ومشاعره ويطمئنه، فيشعر الطفل بالاحترام والمشاركة."},{"h":"أسلوب القص","x":"تتخذ الأسرة من القصص الواقعية أداة لشرح الواقع وعاقبة السيئ والحسن من المواقف."}]}],"quiz":[{"q":"يذكّر أب ابنه: أتذكر يوم ضربك فلان وصرت تبكي؟ ما حكم الكتاب على هذا الأسلوب؟","o":["خطأ يجب أن يتوقف فوراً","أسلوب نافع لشحذ همته","تذكير مقبول إن كان بلطف","وسيلة لتعليمه الواقعية"],"why":"هذا كله خطأ، ويجب أن يتوقف فوراً.","pg":102},{"q":"سئل ابنك: كيف حالك؟ أي جواب يوافق ما يعلمه الكتاب للأطفال؟","o":["الحمد لله في أفضل حال","ماشي الحال والأيام تمر","لا بأس، والأوقات صعبة","نقطّع الأوقات تقطيعاً"],"why":"علّم الطفل إذا قلت له: كيف حالك أن يقول: الحمد لله في أفضل حال","pg":102},{"q":"نصح قريب أباً بإخراج ابنه الراسب في الرابع الابتدائي ليتعلم مهنة. كيف يصف الكتاب ذلك؟","o":["نصيحة مدمرة لنفسية الطفل","نصيحة واقعية تناسب ظروفه","نصيحة مفيدة إن كان ضعيفاً","نصيحة مقبولة بعد رسوب ثانٍ"],"why":"إن مثل هذه النصائح مدمرة لنفسية الطفل","pg":105},{"q":"أي شرط ينفي الكتاب لزومه حتى يكون المرء متميزاً؟","o":["التفوق في كل سنوات الدراسة","التركيز على ما يحبه ويميل إليه","امتلاك القدرة على الإبداع فيه","بذل الجهد فيما يتقنه من عمل"],"why":"يجب أن نشرح للأبناء أنه لا يشترط للمرء حتى يكون متميزاً أن يكون متفوقاً في كل سنوات دراسته، أو في جميع المواد","pg":107},{"q":"لماذا يحذر الكتاب من تخويف الصغار بالجان والعفاريت والأشباح؟","o":["لأنه يدفعهم إلى التفكير الخرافي","لأنه يجعلهم أكثر جرأة على الكبار","لأنه يقوي خيالهم الإبداعي","لأنه يقربهم من رؤية الواقع"],"why":"ويبالغ بعضهم في ذلك مبالغة كبيرة إلى حد دفع الأطفال في طريق التفكير الخرافي!","pg":110}],"scene":{"t":"ديون الأب","x":"تثقلك ديون متراكمة، وسألك ابنك ذو الثماني سنوات: لماذا أنت مهموم دائماً؟","opts":["لا تحدثه عن الديون الآن، وتؤجل المكاشفة حتى يكبر","تشرح له تفاصيل الديون كلها حتى يكون واقعياً","تخبره أن الأسرة على وشك الإفلاس ليقتصد"],"why":"ليس من الصواب أن نحدّث طفلاً في الثامنة من عمره عن الديون المتراكمة على أبيه","pg":111},"rel":[{"b":"kids","ci":4,"t":"الشعور بالدونية"}]},{"k":"c8","t":"التفكير الناقد والتفكير الموضوعي","q":"كيف نعلم الطفل أن يقوّم الأفكار ويحكم بإنصاف بعيداً عن الظنون والأهواء؟","essence":"انقد لتصلح، وتثبت قبل أن تحكم","kw":["النقد","الأسئلة","الموضوعية"],"sections":[{"t":"معنى النقد ومكانته","pg":113,"key":"إذن النقد لا يهدف إلى بيان العيوب فحسب، كما هو شائع.","p":["التفكير النقدي نشاط ذهني راقٍ جداً، بل هو أرقى أنواع التفكير"],"items":[{"h":"النقد تقويم","x":"يعني تقويم الأفكار والأحداث والسلوكات وتوضيح ما فيها من صواب وخطأ وجمال وقبح."},{"h":"نقد غير معصوم","x":"لا نتوقع نقداً بلا خلل، فالناقد يعبر عن وجهة نظر شخصية، وليس على الطفل أن يتقبل كل نقد يوجه إليه."},{"h":"التمركز حول الذات","x":"لدى الطفل ميل إلى التمركز حول ذاته، وفي المراهقة قد تظهر نزعة إلى تسفيه آراء الآخرين، وهي حالة مؤقتة."}]},{"t":"الإيمان بقدرة الطفل وطرح الأسئلة","pg":116,"key":"إن موروثنا الشعبي في المجال التربوي، يفضل الطفل الصامت الممتثل المطيع على الطفل الناقد والمعترض والمدافع عن وجهة نظره","p":["المهم أن يشعر الطفل أنه لا يرتكب خطأ حين يسأل، والمهم أن يتلقى الجواب الصحيح والمقنع."],"items":[{"h":"حديث النخلة","x":"استحيا ابن عمر أن يجيب في مجلس الكبار، فقال له أبوه: لأن تكون قلتها أحب إلي من حمر النعم."},{"h":"تلقي التساؤلات","x":"نستقبل أسئلة الطفل برحابة صدر، فإن كان الوقت غير مناسب قلنا: اسألني حين نكون على العشاء."},{"h":"صياغة الأسئلة","x":"ندرب الأبناء على أدوات الاستفهام: ماذا ولماذا وكيف ومتى وأين ومن، كما في مثال الابن الضعيف في الثالث المتوسط."}]},{"t":"المحاسن والمساوئ والبدائل","pg":119,"key":"حيث إن هدف التفكير النقدي هو الإصلاح والارتقاء وليس التشهير والتشويش","p":["والنقد المنتج هو الذي يساعد على نحو مباشر في الانتقال من حال إلى حال أفضل"],"items":[{"h":"إدراك المحاسن والمساوئ","x":"يعتمد التفكير النقدي عليهما، والناقد الفذ يضع إصبعه على مواطن العظمة والسمو أيضاً."},{"h":"جلسات اللامنهجية","x":"يقسم الطلاب فريقين حول موضوع كالغنى أو الشهرة، فريق للمحاسن وآخر للمساوئ، ويفوز من يكتشف أكثر."},{"h":"مطالبة بالبديل","x":"حين يعرف الطفل أننا سنطالبه بالبديل إذا رفض شيئاً، يقل اندفاعه نحو النقد وتنشغل إمكاناته بالبحث عن حلول."}]},{"t":"التفكير الموضوعي: المعلومات والبعد عن الظنون","pg":121,"key":"إن من الممكن أن نعرّف (التفكير الموضوعي) بأنه: (نشاط عقلي منظم، يستند إلى معلومات جيدة، ويستهدف الوصول إلى الحقيقة والتعامل معها على ما هي عليه بعيداً عن الذاتية والمؤثرات الخارجية)","p":["هذا موقف خاطئ لأن الطفل لم يبذل أي جهد في التحقق من صدق زميله"],"items":[{"h":"جمع المعلومات","x":"قبل أي حكم نجمع أكبر قدر ممكن من المعلومات، وقد نهى القرآن عن اتباع ما ليس لنا به علم."},{"h":"أوهام الأطفال","x":"طفل يظن أباه موسراً فيتوسع في الطلب، وآخر يظن ملاطفة معلمه دليل نباهته فيتجرأ، فنتخذ ذلك فرصة للتوجيه."}]},{"t":"البعد عن الأهواء ونسبية الموضوعية","pg":123,"key":"إن الموضوعية التي يدعيها كل واحد منا لن تكون أبداً كاملة، بل ستكون نسبية ومنقوصة","p":["إن علينا أن نصغي لما يقوله الطفل باهتمام، وبعد ذلك نبدأ بمناقشته وبيان التجاوزات التي ظهرت في كلامه"],"items":[{"h":"الأهواء أصعب","x":"البعد عن الظنون قد يكون أسهل من البعد عن الأهواء، والطفل يميل مع هواه لتأخر نمو حاسته الأخلاقية."},{"h":"أمثلة","x":"طفل يشكو ابن الجيران ويجعل نفسه المعتدى عليه، وآخر يسرف في مدح مدرسه، وثالث يصف أخاه بصفات ليست فيه."},{"h":"اختلاف النظارة","x":"نظرة الأوروبيين أو الصينيين إلى الفتوحات الإسلامية تختلف عن نظرتنا، ونظرتنا إلى واقع الغرب تختلف كذلك."},{"h":"لغة النسبية","x":"ندرب الطفل على كلمات مثل: أظن، يمكن، ربما، لعل، قليل، كثير، بعض."}]}],"quiz":[{"q":"هل يقتصر هدف النقد على بيان العيوب بحسب الكتاب؟","o":["لا، بل يبين الصواب والخطأ معاً","نعم، فهو تتبع العيوب وكشفها للناس","لا، بل يقتصر على ذكر المحاسن","نعم، إذا صدر عن ناقد متخصص"],"why":"إذن النقد لا يهدف إلى بيان العيوب فحسب، كما هو شائع.","pg":114},{"q":"أي طفل يفضله موروثنا الشعبي في المجال التربوي بحسب الكتاب؟","o":["الصامت الممتثل المطيع","الناقد المدافع عن رأيه","كثير الأسئلة والمحاورة","المستقل في أحكامه وآرائه"],"why":"إن موروثنا الشعبي في المجال التربوي، يفضل الطفل الصامت الممتثل المطيع على الطفل الناقد والمعترض والمدافع عن وجهة نظره","pg":116},{"q":"سألك ابنك سؤالاً وأنت منشغل بضيوفك. ما التصرف الذي يقترحه الكتاب؟","o":["تخبره أن الوقت غير مناسب وتؤجل الجواب","تنهاه عن كثرة الأسئلة أمام الناس والضيوف","تعطيه جواباً سريعاً ولو غير صحيح","تتجاهل سؤاله حتى ينساه هو من نفسه"],"why":"نعم يمكن أن نقول للطفل: الوقت غير مناسب الآن للإجابة على سؤالك، اسألني حين نكون على العشاء","pg":117},{"q":"ما الهدف الذي يجعل النقد منتجاً بحسب الكتاب؟","o":["الإصلاح والارتقاء وإيجاد البدائل","التشهير بالأخطاء وكشف أصحابها للناس","إثبات تفوق الناقد على غيره دائماً","الاعتراض على كل فكرة جديدة تطرح"],"why":"حيث إن هدف التفكير النقدي هو الإصلاح والارتقاء وليس التشهير والتشويش","pg":120},{"q":"قال زميل لابنك: فلان ذمك في غيابك، فصدقه فوراً وغضب. لماذا يعد الكتاب موقفه خاطئاً؟","o":["لأنه لم يتحقق من صدق ما نقل إليه","لأنه لم يرد على من ذمه بالمثل فوراً","لأنه أخبر أهله بما سمعه من زميله","لأنه لم يقاطع الزميلين معاً"],"why":"هذا موقف خاطئ لأن الطفل لم يبذل أي جهد في التحقق من صدق زميله","pg":123}],"scene":{"t":"شكوى من ابن الجيران","x":"جاءك ابنك يشكو ابن الجيران بعد نزاع بينهما، ويصور نفسه المعتدى عليه، مع أنه قد يكون هو المعتدي.","opts":["تصغي إليه باهتمام، ثم تناقشه وتبين له ما تجاوز فيه","تصدقه وتذهب فوراً لمعاتبة أهل الجار","تعاقبه مباشرة لأنك تظن أنه المخطئ"],"why":"إن علينا أن نصغي لما يقوله الطفل باهتمام، وبعد ذلك نبدأ بمناقشته وبيان التجاوزات التي ظهرت في كلامه","pg":125}},{"k":"c9","t":"تكوين المفاهيم: الحوار المثمر","q":"لماذا نهتم ببناء المفاهيم، وكيف نعلم الطفل الحوار المثمر؟","essence":"الحوار لإضاءة الحق لا لكسب الغلبة","kw":["المفاهيم","الحوار","الإنصات"],"sections":[{"t":"قصور المفاهيم وصناعتها","pg":131,"key":"إن الملاحظ هو أن (قصور المفاهيم) يشكل عاملاً مشتركاً بين كل المشكلات والأزمات التي تعاني منها الأمة","p":["إن صناعة المفاهيم هي عمل فلسفي أصيل، وهي تتطلب الكثير من الصبر والإتقان والدقة"],"items":[{"h":"الاختلاف في التعريفات","x":"إذا اختلفنا في التعريفات والمعايير لم نتفق على شيء، فتكون الفوضى ثم الاقتتال."},{"h":"الجزر المتناثرة","x":"قال أحد الفلاسفة: إن مفهوماتنا الواضحة تشبه الجزر المتناثرة فوق صفحة المحيط الغامض."},{"h":"النقاش المفتوح","x":"الأسئلة المتبادلة بين الكبار والصغار من أفضل وسائل إنضاج المفاهيم الأساسية."}]},{"t":"معنى الحوار وهدفه","pg":133,"key":"لا يهدف الحوار المثمر إلى إشعال الخصومة بين المتحاورين، ولا ينبغي لهم أن يستخدموه أداة لإظهار التفوق على الخصوم أو وسيلة لإظهار الامتياز الشخصي، وإنما يهدف إلى إضاءة النقاط المظلمة","p":["الحوار إذن يدل على الندية بين المتحاورين وعلى قبول كلا المتحاورين بالاستماع لصاحبه","والله ما ناظرت أحداً إلا أحببت أن يُظهر الله الحق على لساني أو لسانه"],"items":[{"h":"دور الآباء","x":"قد لا يملك كثير منهم الخبرة لشرح المفاهيم العميقة، لكنهم يستطيعون تهيئة الطفل للحوار بتعليمه أدب الحديث والاستماع."},{"h":"شرح وجهة النظر","x":"إذا أردت للحوار أن يثمر فاحرص على الشرح المفصل لوجهة نظرك، وتذكر أنها تحتمل الصواب والخطأ."}]},{"t":"آداب الحوار المثمر","pg":136,"key":"المحاور الجيد يحرص على سماع محاوره، والاستفادة منه، إنه يطبق القاعدة العظيمة: (عامل الناس كما تحب أن يعاملوك)","p":["نحن لا نشترط أن يتكلم الجميع على قدم المساواة، لكن نشترط أن يشعر الكل أن أمامهم فرصة للتحدث، وأن يطلبوا من بعضهم بعضاً المشاركة في الحوار."],"items":[{"h":"الالتزام بالموضوع","x":"الحوار المثمر لا يكون حول كل شيء، فإذا خرج المحاور عن الموضوع قلنا له بلطف: لنعد إلى ما اتفقنا عليه."},{"h":"التشجيع","x":"نشجع المحاور بالنظر إليه وتحريك الرأس وكلمات مثل: جميل، ممتاز، واضح، طيب."},{"h":"عند الاحتداد","x":"نخفض صوتنا، ونعطي المحاور فرصة للدفاع عن نفسه، ونثني على بعض أفكاره، فالمسألة ليست هزيمة أو انتصاراً."},{"h":"دقة الألفاظ","x":"يقال: لا ينبغي لي أن أرفع صوتي، بدل: لا يجب علي أن أحاوره بصوت هادئ، ويقال: لا أوافق على معظم ما قلتموه، بدل: كل ما قلتموه مرفوض."}]},{"t":"الاستعداد للحوار وختامه","pg":139,"key":"(مذهبنا صواب، يحتمل الخطأ، ومذهب غيرنا خطأ يحتمل الصواب)","p":["علامة الوصول إلى طريق مسدود واضحة، وهي كثيراً ما تتمثل في تكرار الطروحات والأدلة والردود"],"items":[{"h":"الاستعداد","x":"ترتيب الأفكار والأسئلة والأدلة قبل الحوار، واستبعاد البرهان الضعيف لأنه يستخدم ضد صاحبه."},{"h":"القطعي والظني","x":"لا يفاوض المرء على ما لديه من أمور يقينية، أما الأفكار الظنية والاجتهادية فنتائج الحوار قد ترسخها أو تخلصنا منها."},{"h":"خاتمة الحوار","x":"نخفض التوتر ونعبر عن التقدير للمحاور، ونلخص ما اتفقنا عليه وما بقي موضع نزاع."}]}],"quiz":[{"q":"ما العامل المشترك بين كل المشكلات والأزمات التي تعاني منها الأمة بحسب الكتاب؟","o":["قصور المفاهيم","ضعف الاقتصاد","كثرة عدد السكان","نقص في المدارس"],"why":"إن الملاحظ هو أن (قصور المفاهيم) يشكل عاملاً مشتركاً بين كل المشكلات والأزمات التي تعاني منها الأمة","pg":131},{"q":"ما الذي يهدف إليه الحوار المثمر في الأصل؟","o":["إضاءة النقاط المظلمة","إظهار التفوق على الخصم","تحقيق الغلبة في النقاش","إثبات الامتياز الشخصي"],"why":"وإنما يهدف إلى إضاءة النقاط المظلمة","pg":134},{"q":"علت نبرة محاورك واحتد في جداله. ما الذي يوصي به الكتاب؟","o":["تخفض صوتك وتعطيه فرصة ليدافع عن نفسه","ترفع صوتك حتى يعود إلى الهدوء","تنهي الحوار فوراً وتترك المجلس","تذكره بأخطائه السابقة أمام كل الحاضرين"],"why":"إذا علت نبرة محاورك، واحتد في جداله، فحاول استيعابه من خلال خفض صوتك وإعطائه فرصة أكبر ليدافع عن نفسه","pg":137},{"q":"قال طفل لفريق يحاوره: كل ما قلتموه مرفوض. ما العبارة الأدق التي يقترحها الكتاب؟","o":["إني لا أوافق على معظم ما قلتموه","كلامكم كله خطأ ولا يستحق أي نقاش","سأصمت لأنكم لا تفهمون رأيي","لن أشارك في حواركم مرة أخرى"],"why":"وكان عليه أن يقول: إني لا أوافق على معظم ما قلتموه أو كثير مما قلتموه.","pg":138},{"q":"متى تكون الحكمة في التوقف عن الحوار بحسب الكتاب؟","o":["حين تتكرر الطروحات والأدلة والردود","حين يخالفك المحاور في أول فكرة يطرحها","حين يتجاوز الحوار ساعة كاملة","حين يقترح أحد الحاضرين موضوعاً آخر"],"why":"علامة الوصول إلى طريق مسدود واضحة، وهي كثيراً ما تتمثل في تكرار الطروحات والأدلة والردود","pg":140}],"scene":{"t":"الصامت في الحوار","x":"تدير حواراً بين أبنائك حول قضية في البيت، وأحدهم يميل إلى الصمت لا يشارك، فيتساءل أخوه: هل يجب أن يتكلم؟","opts":["تحرص على أن يشعر الجميع أن أمامهم فرصة للحديث، دون اشتراط التساوي","تلزمه بالحديث مثل إخوته تماماً حتى يتعود","تتركه وشأنه لأن الحوار للمتكلمين فقط"],"why":"نحن لا نشترط أن يتكلم الجميع على قدم المساواة، لكن نشترط أن يشعر الكل أن أمامهم فرصة للتحدث، وأن يطلبوا من بعضهم بعضاً المشاركة في الحوار.","pg":137},"rel":[{"b":"read","ci":6,"t":"الحوار مع الكاتب"},{"b":"fam","ci":5,"t":"الحوار بين الزوجين"}]},{"k":"c10","t":"تكوين المفاهيم: الحكم على الأشياء","q":"كيف ندرب الطفل على إصدار أحكام دقيقة ومنصفة؟","essence":"تريّث، وميّز نوع الحكم، وأنصف ولو على نفسك","kw":["التريث","أنواع الحكم","الإنصاف"],"sections":[{"t":"التريث في إصدار الأحكام","pg":141,"key":"التريث في إصدار الأحكام خلق عظيم وعادة حميدة","p":["إن من مسؤوليتنا نحن الكبار أن نوضح للصغار أن أحكامنا التي نصدرها على الأشياء والأحداث، لا تكون دائماً صحيحة"],"items":[{"h":"حق الطفل في الحكم","x":"نشجع الأطفال على أن يكون لهم حكمهم الخاص، بل ندربهم على ذلك، لأن موقفهم من الأحداث ينعكس على عقليتهم."},{"h":"تعليل خاطئ","x":"طفل يقول: معلمي لا يحبني، لأنه نبهني حين تكلمت دون إذن، وآخر يتهم ابن الجيران بالتجسس لأنه رآه أمام الباب."},{"h":"الكبار ليسوا دائماً على حق","x":"القرآن ذم التقليد الأعمى للآباء، وسكوت الكبار عن أمر لا يدل على إباحته، فقد يسكتون خوفاً أو حياء."}]},{"t":"أنواع الأحكام","pg":144,"key":"هذا الحكم من الطفل حكم شخصي، والحكم الشخصي يظل قابلاً للصواب والخطأ، ومن هنا فينبغي أن نعبر عنه برفق","p":["إذ إن لكل واحد من الصغار ذوقه الشخصي الذي لا يحتمل أي نقاش."],"items":[{"h":"الحكم الذوقي","x":"كلون الثوب ونوع الطعام، فلا يعترض الطفل على ملابس إخوته أو تنظيم أثاث البيت."},{"h":"الحكم الاجتماعي","x":"يتبدل من بلد إلى بلد ومن زمان إلى زمان، كجلوس صاحب البيت مع ضيوفه أو سؤال الضيف عن جوعه."},{"h":"الحكم القانوني","x":"الصيد في محمية ممنوع بالقانون، والقانون يتغير، فالأحكام القانونية تقبل النقاش والاعتراض."},{"h":"الحكم الشرعي","x":"كمنع المحرم من الصيد، حكم تعبدي يمتثله المسلم بالإيمان والتسليم، ونستثمره في تنمية الإيمان والانتماء."}]},{"t":"الدقة في صياغة الأحكام","pg":146,"key":"إن الدقة في استخدام اللغة تعبر دائماً عن تقدم في الفكر وارتقاء في المعرفة","p":[],"items":[{"h":"ألفاظ غير دقيقة","x":"بعضهم يستعمل كلمة حرام لكل ما لا يعجبه، وكلمة ممتاز جداً لكل ما يرضيه."},{"h":"المصطلح الشرعي","x":"نوضح أن العمل قد يكون مندوباً أو مستحباً أو مسنوناً أو واجباً، أو مكروهاً أو محرماً أو مخالفاً للأولى."},{"h":"كلمات الذوق","x":"نرشد الأطفال إلى كلمات مثل: لطيف، لائق، مناسب، غير مناسب، ونعلمهم مواضع استخدامها."}]},{"t":"الإنصاف وترك المبالغة في حب الذات","pg":147,"key":"إن كثيراً من الأطفال في بيئاتنا الإسلامية يسمعون يومياً العبارات التي تحط من شأن الأعداء، وترفع من شأن الأهل والأقرباء، وهذا يشكل عقلياتهم على نحو مشوّه","p":["علينا أن نعترف أننا كثيراً ما نبالغ في حب أنفسنا وأولادنا وأقربائنا","فالمسألة مسألة قيام لله تعالى بالقسط والعدل، وليست مسألة ربح أو خسارة."],"items":[{"h":"مدح الذات","x":"بعض الناس يمدح أسلوبه وآباءه وأثاث بيته، ويهون من شأن الآخرين، وهذا من الظلم والحيف."},{"h":"التوجيه القرآني","x":"نهى القرآن عن تزكية النفس، وعن بخس الناس أشياءهم، وذكر أن تفضيل النفس على الغير عمل شيطاني."},{"h":"قول الحق","x":"نريد أن نسمع من الأطفال الحق المجرد ولو مس مصالحنا، وننهاهم عن الباطل ولو انطوى على الثناء على الذات."}]}],"quiz":[{"q":"قال طفل: معلمي لا يحبني، لأنه نبهه مرة حين تكلم دون إذن. كيف يقوّم الكتاب حكمه؟","o":["حكم غير صحيح لأن تعليله غير صحيح","حكم صحيح لأن المعلم نبهه أمام زملائه","حكم ذوقي لا يحتمل أي نقاش أو مراجعة","حكم ثابت لا يقبل المراجعة أبداً"],"why":"وإذا فتشنا في الحالتين وجدنا أن التعليل غير صحيح، وبالتالي فإن حكم الصغير أيضاً غير صحيح","pg":143},{"q":"لماذا نوضح للصغار أن سكوت الكبار عن أمر لا يعني أنه مباح؟","o":["لأن الكبار قد يسكتون خوفاً أو حياءً","لأن السكوت علامة الرضا في كل حال ومقام","لأن الكبار لا يخطئون في أحكامهم","لأن الصغار لا يفهمون معنى السكوت"],"why":"فقد نسكت خوفاً من وقوع فتنة، وقد نسكت حياء ممن وقع في الخطأ","pg":144},{"q":"أُخرج طالب من الفصل عقوبة، فقال زميل: المعلم كان قاسياً. ما نوع هذا الحكم؟","o":["شخصي يحتمل الصواب والخطأ","شرعي ثابت لا يقبل النقاش","ذوقي لا يوصف بالخطأ أبداً","قانوني يتغير بتغير الزمن"],"why":"هذا الحكم من الطفل حكم شخصي، والحكم الشخصي يظل قابلاً للصواب والخطأ، ومن هنا فينبغي أن نعبر عنه برفق","pg":144},{"q":"ماذا تعبر عنه الدقة في استخدام اللغة بحسب الكتاب؟","o":["تقدم في الفكر وارتقاء في المعرفة","تكلف في الكلام لا حاجة إليه أصلاً","حرص زائد على إرضاء المستمعين","ميل إلى المبالغة في التعبير"],"why":"إن الدقة في استخدام اللغة تعبر دائماً عن تقدم في الفكر وارتقاء في المعرفة","pg":146},{"q":"يسمع أطفال كل يوم عبارات تحط من الأعداء وترفع الأهل. ما أثر ذلك عليهم بحسب الكتاب؟","o":["تشكيل عقلياتهم على نحو مشوه","تقوية انتمائهم على نحو سليم","تنمية قدرتهم على النقد الذاتي","تعليمهم الإنصاف مع المخالفين"],"why":"وهذا يشكل عقلياتهم على نحو مشوّه","pg":148}],"scene":{"t":"ثوب الأخ","x":"سخر ابنك من لون ثوب اشتراه أخوه، ووصفه بأنه قبيح، فحزن أخوه.","opts":["تبين له أن المسألة ذوقية، فلا يعترض على ملابس أخيه","توافقه لأن ذوقه في الألوان أفضل","تطلب من أخيه تغيير الثوب حتى ينتهي الخلاف"],"why":"وهكذا فإننا نستطيع تعليم الطفل ألا يعترض على ملابس بعض إخوته أو بعض زملائه، وألا يعترض على تنظيم خالته لأثاث بيتها؛ لأن المسألة ذوقية.","pg":145}},{"k":"c11","t":"تكوين المفاهيم: الصداقة","q":"ما الصداقة الحقيقية، وكيف يختار الطفل أصدقاءه ويرعى صداقتهم؟","essence":"الصداقة اكتشاف تحفظه التضحية","kw":["الصديق","الاختيار","التضحية"],"sections":[{"t":"من هو الصديق؟","pg":149,"key":"الصديق في لغة العرب: هو ذلك الصاحب الصادق في مودته ومحبته","p":["إن الأصدقاء درجات، والأصدقاء الممتازون، لا يكونون في العادة كثيرين، وإذا ظفر أحدنا بثلاثة أو أربعة من الأصحاب الذين تتوفر فيهم الصفات التي ذكرناها، فذلك فضل كبير من الله تعالى."],"items":[{"h":"أهمية المفهوم","x":"الأطفال أشد حاجة من الكبار إلى الأصدقاء، ويتعلقون بهم تعلقاً كبيراً ويتأثرون بهم."},{"h":"صفات الصديق","x":"يشتاق إليك إذا غبت، ويضحي من أجلك، ويرجو لك الخير، ولا يحسدك ولا يشمت بك."},{"h":"طريقة الشرح","x":"يعرض المؤلف المفهوم في صورة أسئلة يطرحها الطفل وأجوبة يقدمها المربي."}]},{"t":"أسئلة الطفل عن الصداقة","pg":150,"key":"والصديق قد يكون جاراً لنا، كما أن الجار قد لا يكون صديقاً.","p":["لكن من المعروف أن ندرة التحادث بين الصديقين تُحدث نوعاً من التباعد بينهما","أما الشجار العنيف فلا يقع بين الأصدقاء الحقيقيين."],"items":[{"h":"الاختلاف لا يفسدها","x":"الأصدقاء يختلفون حول بعض المسائل، أما رفع الصوت والسباب والضرب فلا يقع إلا نادراً."},{"h":"العدو والصديق","x":"لا يكون المرء صديقاً وعدواً في آن واحد، لكن العدو قد يصير صديقاً إذا زالت أسباب العداوة."},{"h":"الصداقة قربة","x":"إذا قامت على تقوى الله وخلت من المصالح الدنيوية، كما في حديث المتحابين في الله."},{"h":"دوام الصداقة","x":"الأصل فيها الاستمرار، لكن ظروفاً قد تفرقها كالسفر، وصداقات الدول تقوم على المصالح."}]},{"t":"اختيار الصديق","pg":153,"key":"والحقيقة أن عملية اختيار الصديق هي عملية اكتشاف","p":["ومن المألوف أن يصادق خمسة أو ستة من الأطفال، ثم لا يبقى له إلا صديق واحد، وقريب من هذا يحدث مع بعض الكبار."],"items":[{"h":"خيبة الظن","x":"حين يتبين للطفل أن صديقه لا يصلح، فهذا يعني أن الاكتشاف لم يكن صحيحاً، وهو أمر طبيعي."},{"h":"من لا أصدقاء لهم","x":"قليلون جداً، ومنهم الأطفال المشاكسون والانطوائيون، وعلى كل طفل أن يكون من الفئة المحبوبة."}]},{"t":"رعاية الصداقة","pg":154,"key":"العلاقات الاجتماعية على اختلاف أنواعها تشكل مصدراً كبيراً لإسعادنا وطمأنينتنا، ولهذا فإن علينا أن نحرص عليها، والحرص عليها يتجلى في شيء واحد، هو (التضحية) من أجلها.","p":["وحين يريد المرء للصداقة أن تستمر فلا بد من أن يغض الطرف عن أخطاء صديقه، ويتغافل عنها."],"items":[{"h":"الكرم والبذل","x":"دعوة الصديق إلى البيت، وإيصاله بالسيارة، وتقديم الهدية في المناسبات."},{"h":"الحرص على مصلحة الصديق","x":"أهمها إعانته على الاستقامة، والصديق الصدوق ينصح صديقه ويوضح له عيوبه."},{"h":"تحمل الأذى","x":"الصديق قد يؤذي صديقه من غير قصد، أو في لحظة ضعف، فيصبر عليه."}]}],"quiz":[{"q":"من هو الصديق في لغة العرب كما ينقل الكتاب؟","o":["الصاحب الصادق في مودته ومحبته","القريب الذي يسكن بجوارك دائماً","الزميل الذي يشاركك الدراسة","كل من تتحدث معه باستمرار كل يوم"],"why":"الصديق في لغة العرب: هو ذلك الصاحب الصادق في مودته ومحبته","pg":149},{"q":"سأل الطفل: هل كل من نعرفهم من الجيران أصدقاء لنا؟ بماذا يجيب المربي؟","o":["لا، فقد لا يكون الجار صديقاً","نعم، لأن الجوار يوجب الصداقة","نعم، إذا كان الجار من الأقارب","لا، فالجار لا يصلح أن يكون صديقاً"],"why":"والصديق قد يكون جاراً لنا، كما أن الجار قد لا يكون صديقاً.","pg":150},{"q":"ما الذي يُحدث نوعاً من التباعد بين الصديقين ويضعف عرى الصداقة؟","o":["ندرة التحادث بينهما","الاختلاف في بعض الآراء","كثرة الأصدقاء لدى أحدهما","التنافس في الدراسة واللعب"],"why":"لكن من المعروف أن ندرة التحادث بين الصديقين تُحدث نوعاً من التباعد بينهما","pg":150},{"q":"أي شجار لا يقع بين الأصدقاء الحقيقيين بحسب الكتاب؟","o":["الشجار العنيف بالضرب والأذى","الاختلاف في وجهات النظر","النقاش الهادئ حول بعض المسائل","النقاش الهادئ حول المسائل"],"why":"أما الشجار العنيف فلا يقع بين الأصدقاء الحقيقيين.","pg":151},{"q":"في أي شيء يتجلى الحرص على العلاقات الاجتماعية بحسب الكتاب؟","o":["التضحية من أجلها","كثرة الهدايا فيها","المجاملة في كل حال","ترك النصح والمكاشفة"],"why":"والحرص عليها يتجلى في شيء واحد، هو (التضحية) من أجلها.","pg":154}],"scene":{"t":"خيبة في صديق","x":"عاد ابنك حزيناً لأن صديقاً اختاره في بداية العام خيب ظنه، وهو يقول: لن أصادق أحداً بعد اليوم.","opts":["تشرح له أن اختيار الصديق اكتشاف، وأن خيبة الظن في بعضهم أمر مألوف","تؤيد قراره لأن الأصدقاء لا يجلبون إلا المتاعب","تختار له أنت أصدقاءه من أبناء الأقارب"],"why":"ومن هنا وجب أن نوضح له أن من المألوف جداً أن يخيب ظن الطفل في بعض أصدقائه","pg":153}}],"highlights":[{"x":"حاول دائماً أن تمنح ابنك فرصة ثانية.","pg":23},{"x":"على المربي أن يتذكر دائماً أنه الطرف الناضج.","pg":36},{"x":"لنتعامل مع أخطاء الصغار على أنها زلات من أشخاص طيبين.","pg":49},{"x":"الإسراف في منح الثناء يُفقده المعنى، ويفرغه من قوة الإثارة، ولهذا فالاعتدال دائماً مطلوب..","pg":58},{"x":"شجع الطفل على تكرار المحاولة، إذ قلما يصيب المرء النجاح من المحاولة الأولى...","pg":64},{"x":"لا تكمن ميزتنا الأساسية في أن لدينا أدمغة، وإنما في كوننا نستخدمها..","pg":68},{"x":"النفوس الكبيرة تبتهج بالحق، وتحترم الحقيقة..","pg":82},{"x":"كلما كانت مهاراتنا التربوية أعلى كانت حاجتنا إلى استخدام العقوبة أقل..","pg":86},{"x":"الطفل الذي يعيش في بيئة آمنة يتعلم حسن الظن، والطفل الذي يعيش في بيئة كثيرة الشكوى يتعلم الشجب..","pg":104},{"x":"القلق لا يجرد المستقبل من مآسيه لكنه يجرد الحاضر من أفراحه..","pg":106},{"x":"التفكير الجيد مهارة، يصنعها التدريب","pg":123},{"x":"الألم شيء محتوم، لكن التعاسة شيء اختياري.","pg":141}],"concepts":[{"term":"العقلية","def":"إذ إن عقلية الواحد منا ليست ما لديه من أفكار ومعلومات، وإنما هي أعم من ذلك، إنها تشمل المصطلحات والتعريفات التي نعتمدها في التعامل مع الأشياء إلى جانب شمولها للطرق والأساليب التي نفكر من خلالها","pg":10},{"term":"مرحلة التساؤل","def":"وقد أطلق أحد الباحثين على هذه المرحلة اسم (مرحلة التساؤل) حيث تدل بعض الدراسات على أن ما بين (10% إلى 15%) من حديث الطفل في هذه المرحلة يكون عبارة عن أسئلة.","pg":16},{"term":"الذات","def":"إن الذات تعني ذلك التكوين المعرفي المنظم للمدركات الشعورية والتصورات والتعميمات الشخصية","pg":27},{"term":"التفكير","def":"هو تلك العملية العقلية المعرفية الوجدانية التي تستهدف الانتقال من المعلوم إلى المجهول","pg":76},{"term":"التفكير الإبداعي","def":"إن التفكير الإبداعي عبارة عن نشاط ذهني منظم، يؤدي إلى نتائج وحلول تتصف بالجدة والأصالة.","pg":91},{"term":"الطلاقة","def":"وهي تعني القدرة الجيدة على التوليد: توليد الأفكار وتوليد الكلمات والجمل والتعبيرات","pg":94},{"term":"المرونة","def":"وهي تعني رحابة عقل الإنسان في رؤية الأشياء وتفسير الأحداث","pg":95},{"term":"الأصالة","def":"لكن الأصالة لا تقتصر على الجدّة، وإنما تعنى أيضاً النفع والفائدة","pg":97},{"term":"التفكير الإيجابي","def":"الذي يفكر على نحو إيجابي، يقوم بإدارة عواطفه، ويستخدم اللغة على نحو مشجع ومحفز، كما يحاول أن يرى الوجه المشرق للأشياء.","pg":127},{"term":"التفكير الواقعي","def":"التفكير الواقعي هو تفكير من يرى العالم على ما هو عليه من غير تجميل أو تشويه.","pg":127},{"term":"النقد","def":"النقد قبل كل شيء يعني قيام الناقد بتقويم الأفكار والأحداث والسلوكات، وتوضيح ما فيها من صواب وخطأ وجمال وقبح وخير وشر..","pg":113},{"term":"التفكير الموضوعي","def":"(نشاط عقلي منظم، يستند إلى معلومات جيدة، ويستهدف الوصول إلى الحقيقة والتعامل معها على ما هي عليه بعيداً عن الذاتية والمؤثرات الخارجية)","pg":122},{"term":"الحوار","def":"الحوار إذن يدل على الندية بين المتحاورين وعلى قبول كلا المتحاورين بالاستماع لصاحبه","pg":133},{"term":"الصديق","def":"الصديق في لغة العرب: هو ذلك الصاحب الصادق في مودته ومحبته","pg":149}],"links":[{"topic":"القراءة","pg":19},{"topic":"الاعتراف بالخطأ والعقوبة","pg":38},{"topic":"الكذب","pg":35},{"topic":"العمل والفراغ","pg":62},{"topic":"اللعب والمرح","pg":86},{"topic":"الإبداع","pg":91},{"topic":"التفكير الناقد","pg":113},{"topic":"أسئلة الأطفال","pg":116},{"topic":"الحوار","pg":133},{"topic":"الصداقة","pg":149}]};
